import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5


def test_conversion_rate_empty():
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}, {"converted": None}, {"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_conversion_rate_without_sessions(groups):
    assert pooled_conversion_rate(groups) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 6), (10, 7)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 4], days) == expected


def test_parse_session_log_flags_and_whitespace():
    assert parse_session_log([" a , 1 , 1 ", "b,2,0", "c,3, \n"]) == [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": False},
        {"id": "c", "day": 3, "converted": None},
    ]


def test_parse_session_log_skips_blank_lines_and_comments():
    assert parse_session_log(["", " \t\n", "  # a,1,0", "b,2,1"]) == [
        {"id": "b", "day": 2, "converted": True},
    ]


@pytest.mark.parametrize("bad_line", ["only,2", "extra,2,1,field", "bad,Monday,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log([" ", " # comment", "ok,1,1", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_then_sorts():
    earlier = {"id": "b", "day": 4, "converted": True}
    later = {"id": "b", "day": 2, "converted": False}
    same_day = {"id": "a", "day": 2, "converted": True}
    first_day = {"id": "z", "day": 1, "converted": None}
    assert dedupe_sessions([earlier, same_day, first_day, later]) == [
        first_day, same_day, later,
    ]


def test_daily_conversion_counts_includes_gaps_and_excludes_outside_days():
    events = parse_session_log([
        "a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,4,1", "g,5,1",
    ])
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], 1, 2) == [0, 0]


def test_campaign_summary_uses_calendar_window_and_pooled_rate():
    groups = {
        "a": parse_session_log(["a,1,1"]),
        "b": parse_session_log(["b,4,1", "c,5,0"]),
        "empty": [],
    }
    assert campaign_summary(groups, 1) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "a": [{"converted": True}],
        "empty": [],
        "zero": [{"converted": False}],
    }
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 10) == ["a", "z", "zero"]


def test_conversion_rate_by_group_sorts_names_and_marks_empty_groups():
    groups = {"z": [{"converted": False}], "a": [], "b": [{"converted": True}]}
    assert list(conversion_rate_by_group(groups).items()) == [
        ("a", None), ("b", 1.0), ("z", 0.0),
    ]


@pytest.mark.parametrize("counts, expected", [([], 0), ([0, -1], 0), ([1, 2, 0, 1, -1, 1], 2)])
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected

