"""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """The conversion rate of a list of sessions. See SPEC.md section 1."""
    hits = sum(1 for e in events if e["converted"] is True)
    return hits / len(events) if events else 0.0


def pooled_conversion_rate(groups):
    """The pooled conversion rate across groups of sessions. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    hits = sum(1 for events in groups.values() for e in events if e["converted"] is True)
    return hits / total if total else 0.0


def conversions_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    return sum(daily_counts[-days:]) if days > 0 else 0


def conversion_rate_by_group(groups):
    """The conversion rate of each group. See SPEC.md section 9."""
    return {name: conversion_rate(groups[name]) if groups[name] else None for name in sorted(groups)}


def longest_conversion_streak(daily_counts):
    """Longest run of days with converted sessions. See SPEC.md section 10."""
    best = cur = 0
    for c in daily_counts:
        if c > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

